const fs = require('fs');
const path = require('path');

// Create a sample job object here
const sampleJob = {
  id: 'job-123',
  name: 'Process Data',
  status: 'pending'
};

// Define the job tracking file path constant here
const JOBS_FILE_PATH = path.join(__dirname, 'jobs.json');

// Create the readExistingJobs function here
function readExistingJobs() {
  try {
    const data = fs.readFileSync(JOBS_FILE_PATH, 'utf8');
    return JSON.parse(data);
  } catch (error) {
    return [];
  }
}

// Create the writeJobsToFile function here
function writeJobsToFile(jobs) {
  fs.writeFileSync(JOBS_FILE_PATH, JSON.stringify(jobs, null, 2));
}

// Create the isDuplicateJob function here
function isDuplicateJob(job, existingJobs) {
  return existingJobs.some(existingJob => existingJob.id === job.id);
}

// Create the addJob function here
function addJob(job) {
  const existingJobs = readExistingJobs();

  if (isDuplicateJob(job, existingJobs)) {
    return { success: false, message: 'Duplicate job detected' };
  }

  existingJobs.push(job);
  writeJobsToFile(existingJobs);
  return { success: true, message: 'Job added successfully' };
}

